# 新手注释：导入无穷大哨兵，便于统一处理尚未得到有效答案的初始状态。
from math import inf
# 新手注释：导入类型标注工具，用来说明参数和返回值类型，不改变算法执行过程。
from typing import Optional


# 新手注释：定义力扣固定入口类；平台会创建它的实例并调用下面的解题方法。
class Solution:
    # 新手注释：定义本题入口方法，使用递归 DFS + 上下界约束解决这道二叉树问题。
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        # 新手注释：递归检查当前结点是否落在允许区间内，并继续约束左右子树。
        def valid(node: Optional[TreeNode], lower: float, upper: float) -> bool:
            # 新手注释：处理 `node` 为空的边界，避免继续访问不存在的内容。
            if node is None:
                # 新手注释：条件已经确定结果，因此立即返回布尔结果 `True`，结束当前判断。
                return True
            # 新手注释：同时检查多个必要条件，只有组合条件成立才进入这一分支。
            if node.val <= lower or node.val >= upper:
                # 新手注释：条件已经确定结果，因此立即返回布尔结果 `False`，结束当前判断。
                return False

            # 新手注释：直接返回条件判断结果，不再额外转换为 True 或 False。
            return (
                valid(node.left, lower, node.val)
                and valid(node.right, node.val, upper)
            )

        # 新手注释：返回 `valid` 的计算结果，把子问题答案传给调用者。
        return valid(root, -inf, inf)

